function validate([grid, k]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 1000) return 'grid needs 1 to 1000 rows.';
  const cols = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (cols < 1 || cols > 1000) return 'Each row needs 1 to 1000 values.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== cols) return 'Every row must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each cell is a whole number from 0 to 1000.';
  }
  if (!Number.isInteger(k) || k < 1 || k > 1e9) return 'k is a whole number from 1 to 10^9.';
  return null;
}

