function countSubmatrices(grid, k) {
  // Every such submatrix is fixed by its bottom-right cell; add up each one cell by cell.
  let result = 0;
  for (let bottom = 0; bottom < grid.length; bottom++) {
    for (let right = 0; right < grid[0].length; right++) {
      let total = 0;
      for (let r = 0; r <= bottom; r++) for (let c = 0; c <= right; c++) total += grid[r][c];
      if (total <= k) result += 1;
    }
  }
  return result;
}

