function generate(rand, size) {
  const pick = limit => Math.floor(rand() * limit);
  const large = size === 'large';
  const rows = large ? 60 + pick(41) : 1 + pick(4);
  const cols = large ? 60 + pick(41) : 1 + pick(5);
  const cap = large ? 1000 : [0, 3, 10, 1000][pick(4)];
  const grid = Array.from({ length: rows }, () => Array.from({ length: cols }, () => (rand() < 0.2 ? 0 : pick(cap + 1))));
  const total = grid.flat().reduce((sum, v) => sum + v, 0);
  // Aim k at a random fraction of the whole grid's sum so the count lands anywhere from 0 to every cell.
  const k = Math.min(1e9, Math.max(1, rand() < 0.1 ? 1e9 : Math.floor(rand() * (total + 2))));
  return [grid, k];
}
